-- This is an example Hyprland Lua config file.
-- Refer to the wiki for more information.
-- https://wiki.hypr.land/Configuring/Start/

-- Please note not all available settings / options are set here.
-- For a full list, see the wiki

-- You can (and should!!) split this configuration into multiple files
-- Create your files separately and then require them like this:
-- require("myColors")

local config_dir = os.getenv("HOME") .. "/.config/hypr/conf/"

dofile(config_dir .. "hardware.lua")
dofile(config_dir .. "autostart.lua")
dofile(config_dir .. "appearance.lua")
dofile(config_dir .. "binds.lua")

-- Apply Noctalia color templates last (overrides borders/accents dynamically)
local noctalia = dofile(os.getenv("HOME") .. "/.config/hypr/noctalia.lua")
if noctalia and noctalia.apply_theme then
    noctalia.apply_theme()
end

-- For Noctalia Color templates
require("noctalia").apply_theme()
